<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Application\Policy\Formula;

use Throwable;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Access\ConsentPurpose\Application\Service\Visibility\ConsentPurposeEnrichForUpdate;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TenantFormula
{
    use LoggerAwareTrait;
    use TracerAwareTrait;
    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(ConsentPurposeEnrichForUpdate $event): ConsentPurposeEnrichForUpdate
    {
        $this->logDebug("Check TenantFormula Consent purpose");
        $span = $this->startSpan("Check TenantFormula Consent purpose");
        try {
            $identity = $this->context->getIdentity();
            $attr = $event->getAttributes();
            if (!($identity->hasScope("platform:global_access"))) {
                $attr->tenant(new TenantRef($identity->getTenant()))
                ;
            }      return $event;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
